def ledger_for_open_cestas(apps, schema_editor):
    """Each line already in a cesta enters the ledger as added, when it was added."""
    BasketItem, BasketEvent = apps.get_model('mall', 'BasketItem'), apps.get_model('mall', 'BasketEvent')
    for row in BasketItem.objects.select_related('part', 'supplier_item__supplier').iterator():
        entry = BasketEvent.objects.create(user_id=row.user_id, account_id=row.account_id, supplier_item_id=row.supplier_item_id, part_id=row.part_id,
                                           sku=row.part.sku, codigo=row.codigo, brand=row.brand, supplier_name=row.supplier_item.supplier.name,
                                           kind='added', quantity_before=0, quantity_after=row.quantity, source=row.source)
        BasketEvent.objects.filter(pk=entry.pk).update(created_at=row.created_at)


